TASKS = [
 dict(ref='1.2',as_id=91913,version=4,credits=5,assessment='Internal',title='One place, one painting',short='Resolve a significant artwork',official='Produce a significant resolved artwork appropriate to established art making conventions',time='8–10 weeks',theme='How can a painting communicate what one place means to me?',brief='Create one substantial, resolved painting about a place you know. Bring together direct observation, personally meaningful details and an intentional painting approach. Choose a scale and level of complexity that give your idea room to develop; an enlarged classroom exercise alone is not a significant outcome.',materials='Drawing book, your own photographs, graphite, acrylic or watercolour, suitable prepared paper or board, brushes and a mixing palette. Negotiate the support and scale before production.',artists=['gossage', 'maughan', 'sherald', 'cezanne'],artist_prompt='Compare how a remembered place, a garden or a portrait can communicate a personal relationship. Choose the model that best supports the subject of your significant painting.',
 phases=[('Find the story','Visit or closely observe a familiar place. Draw there, photograph your own viewpoints and collect written observations. Identify a detail that matters to you and explain the story you want the painting to carry.'),('Learn the painting language','Compare two relevant artworks. Identify specific conventions such as spatial structure, deliberate edges, underpainting or a restricted palette. Test those methods using your own subject; acknowledge the artists and keep the trials.'),('Plan a substantial outcome','Make several small composition studies. Test the hardest technical passage at the intended working scale. Select a proposal and agree with your teacher how scale, depth, production time and finish will make this a substantial single work.'),('Build and review','Prepare your support and work through the painting in planned stages. Keep progress photographs. At a midpoint conference, identify what the actual painting communicates and decide what needs adjusting. Your decisions should guide the next session.'),('Resolve and present','Unify the composition, resolve distracting or unfinished areas and review technical finish. Present the single artwork with its title and a short account of the conventions used. Keep supporting studies available to establish process and authenticity.')],
 evidence=['One substantial, finished painting that communicates your idea or narrative.','Supporting observations, media trials and composition studies showing the conventions you selected.','Dated progress records and source acknowledgements.'],
 grades=[('Achievement','Use suitable painting methods and recognise the conventions informing your substantial, resolved work.','The final painting communicates a place-based idea through the chosen composition and media.'),('Merit','Maintain consistent command of the media and techniques throughout the work.','Edges, layers, colour mixtures and paint handling remain controlled across difficult as well as easy passages.'),('Excellence','Handle the selected media and techniques skilfully and fluently.','Your technical choices work together confidently to communicate the idea in the resolved artwork.')],
 reflection='Which passage best communicates the meaning of your place? Point to the painting, name the technical choice and explain how it contributes.',teacher='Agree the substantial scope before students start. Assess the resolved artwork holistically; preliminary studies support the production process rather than replace the single outcome. Use the current 91913 exemplars and moderator commentary to calibrate judgements. The suggested timing allows sustained production, rather than treating this as a short drawing study.',watch='A small preliminary study or an unresolved painting cannot replace the substantial final outcome.'),
 dict(ref='1.3',as_id=91914,version=4,credits=5,assessment='External',title='The paint laboratory',short='Explore, connect and evaluate',official='Explore Visual Arts processes and conventions to inform own art making',time='5–6 weeks',theme='How might changing the way I paint change the feeling of my subject?',brief='Investigate your own subject through a practical painting inquiry. Try different processes, connect the discoveries and refine your intentions through further trials. Your evidence should show thinking in progress: the decisions and experiments that inform future artwork.',materials='A3 paper or workbook, your own observed objects or photographs, drawing media, water-based paints, brushes, masking materials and a camera for recording larger trials.',artists=['green', 'karaka', 'fadojutimi', 'hodgkins'],artist_prompt='Try a contrast between flat colour, gestural paint and layered marks. Evaluate the results against your own intention rather than aiming to reproduce an artist’s finished image.',
 phases=[('Set an intention','Choose a subject you can observe and an idea, mood or narrative to investigate. Record your own imagery. Look at the artist resources to identify processes worth testing; the intention remains yours.'),('Experiment with a question','Try a manageable set of related experiments: for example, change paint opacity, edge handling or colour temperature while keeping your subject recognisable. Record the material and process beside each test.'),('Connect the discoveries','Compare the results. Select a useful relationship between two trials, such as a transparent ground and an opaque silhouette, and test it in a new study. Explain how the connection supports or changes your intention.'),('Evaluate through making','Identify a limitation in a promising study. Make a further version that addresses it, then compare the versions. Repeat where useful. Show your reasoning through visual changes and concise, independently written reflections.'),('Select the development evidence','Choose the experiments that make your inquiry legible. Order them so someone can see your intention, connections, revisions and changed thinking. Keep the evidence developmental; a collection of finished paintings alone will conceal the inquiry.')],
 evidence=['A selected portfolio of developmental experiments, connections and iterations.','Reflection in your own words, attached to the trials it discusses.','Your original source imagery and acknowledgements, arranged within the permitted submission format.'],
 grades=[('Achievement','Experiment with materials, techniques and processes in relation to your intention.','Tests investigate how paint choices might communicate the intended mood or idea.'),('Merit','Develop several approaches and connect experiments to generate possibilities.','A later trial combines discoveries from earlier tests for a clear reason.'),('Excellence','Evaluate and refine processes through repeated making and thoughtful selection.','A comparison identifies a limitation; a changed trial addresses it and helps sharpen the intention.')],
 reflection='Which experiment changed your intention most? Explain what you retained, what you rejected and which visual evidence led to that decision.',teacher='Use process demonstrations and generic practice before assessment. During assessed production, keep assistance within NZQA’s permitted conferencing and authenticity conditions. Students must select and reflect independently; do not prescribe a page-by-page response or supply wording for annotations. The activities here are teaching invitations, not a mandated submission template.',watch='A list of techniques is not evaluation. Show what changed because of the experiments.'),
 dict(ref='1.4',as_id=91915,version=3,credits=5,assessment='External',title='Objects that belong',short='Build a sustained related series',official='Create a sustained body of related artworks in response to an art making proposition',time='8–10 weeks',theme='Everyday objects can tell a story about belonging.',brief='Respond to this starting proposition, or negotiate your own: everyday objects can tell a story about belonging. Develop a related series of paintings in which personal objects, pictorial relationships and paint handling work together. Select and order the finished works so the proposition is clear.',materials='Personally meaningful objects, observational drawing materials, your own photographs, water-based paint, suitable paper or board, and materials for the approved portfolio format.',artists=['green', 'white', 'himid', 'hodgkins'],artist_prompt='Investigate how objects and their relationships can communicate belonging. Develop a consistent personal proposition across the series, using the artists as different ways into the question.',
 phases=[('Make the proposition yours','Choose objects you know well. Draw and photograph them yourself, and identify what they suggest about belonging. Rewrite the starting proposition in a way that reflects your own interest.'),('Generate a family of possibilities','Explore objects together and apart. Test cropping, viewpoint, negative space and palette in small painted studies. Investigate a relevant artist method using your own imagery.'),('Develop related works','Follow a promising relationship into further paintings. Let each work respond to a decision in the previous one, rather than repeat the same arrangement. Keep links through subject, process or composition.'),('Strengthen the series','Compare works together. Identify which choices support your proposition and which weaken it. Revisit a problem in a fresh work, aiming for increasingly consistent and skilful paint handling.'),('Edit, order and finish','Select the works that form a clear, finished series. Trial more than one order. Resolve the chosen works and curate the portfolio so thematic, stylistic and technical relationships are visible.')],
 evidence=['A finished series of related artworks responding to your proposition.','A deliberate selection and order that communicates the relationship between works.','Retained process records and source information for authenticity checks.'],
 grades=[('Achievement','Develop connected works that respond to a proposition using relevant art-making processes.','The series has an identifiable subject or intention and visible relationships.'),('Merit','Select a cohesive group and maintain consistency in materials and techniques.','The edited works belong together and the paint handling remains controlled.'),('Excellence','Clarify the proposition through the series while using processes and techniques skilfully.','Each selected work helps the idea become clearer, supported by fluent paint handling.')],
 reflection='If one painting were removed, what would the series lose? Use that question to test whether each selected work contributes.',teacher='Keep this evidence focus separate from 1.3: this standard concerns a finished related body, while 1.3 concerns development and experimentation. If teaching is integrated, retain distinct evidence and judgements for each. Do not prescribe identical outcomes, a fixed number of paintings or a compulsory stylistic formula.',watch='A group of unrelated best paintings does not communicate a sustained proposition.'),
 dict(ref='2.2',as_id=91311,version=2,credits=4,assessment='Internal',title='Seeing the ordinary',short='Apply painting conventions',official='Use drawing methods to apply knowledge of conventions appropriate to painting',time='4 weeks',theme='How can viewpoint, colour and paint surface transform familiar objects?',brief='Use drawing as practical investigation to apply painting conventions to an arrangement of your own objects. Build knowledge by making: drawing includes painted studies, colour studies and collage as well as pencil work. Focus on choosing methods for a particular visual purpose.',materials='Objects, sketchbook, drawing media, collage paper made from your own marks, acrylic or gouache, prepared study supports and a limited set of brushes.',artists=['green', 'bush', 'fadojutimi', 'cezanne'],artist_prompt='Compare flat colour, compressed figure relationships and densely organised garden space. Select conventions for a particular pictorial purpose in your own observed subject.',
 phases=[('Observe a changing arrangement','Set up a small still life from objects you can draw directly. Record different viewpoints and overlaps. Identify a pictorial purpose, such as making the arrangement feel unstable, intimate or monumental.'),('Identify usable conventions','Investigate two artist models. Identify particular spatial, colour and surface conventions, then test their effects with your own arrangement. Label the source and the convention, not just the artist’s name.'),('Make comparative drawing studies','Keep the subject related while changing a deliberate variable: compressed depth versus open depth, warm versus cool modelling, or thin versus opaque paint. Compare the pictorial consequences.'),('Select for a purpose','Choose the methods best suited to your intention. Develop more sustained painted drawings that apply those choices together. Where a method fights your purpose, revise or reject it.'),('Review the application','Lay out the studies so your selection and use of conventions are visible. Explain one successful technical decision and one change. The practical work should demonstrate the knowledge without relying on a long essay.')],
 evidence=['A focused collection of drawing and painting studies applying relevant conventions.','Comparative tests and more sustained studies showing purposeful selection.','Artist and image acknowledgements plus retained process records.'],
 grades=[('Achievement','Apply relevant painting processes and pictorial conventions in practical work.','Studies use colour, space or surface conventions appropriately.'),('Merit','Select and apply particular conventions for an intended purpose.','A chosen palette and spatial structure directly support the intended atmosphere.'),('Excellence','Make critical selections and apply an in-depth knowledge of conventions.','You compare alternatives and combine appropriate methods convincingly for the intended effect.')],
 reflection='Choose two studies. Why is one combination of methods better suited to your intention? Explain using visible features.',teacher='Assess applied knowledge in the drawings, not the quantity of research writing. Confirm local conditions and authenticity procedures, and moderate against the 91311 exemplars. The focus is the selection and application of conventions; a separate series-development task belongs to 2.3.',watch='Copying an artist image can conceal whether you can select conventions for your own purpose.'),
 dict(ref='2.3',as_id=91316,version=2,credits=4,assessment='Internal',title='An idea in motion',short='Develop, clarify and extend',official='Develop ideas in a related series of drawings appropriate to established painting practice',time='5–6 weeks',theme='How can an ordinary object become a metaphor?',brief='Make a related sequence of painted drawings in which an object develops a meaning beyond its everyday use. Begin with an observed subject, identify a conceptual possibility and use subsequent works to test, clarify and extend it. Each decision should make the next drawing necessary.',materials='Your own object studies or photographs, sketchbook, acrylic or gouache, paper, and collage materials generated from your own drawings or marks.',artists=['cotton', 'pick', 'himid', 'hodgkins'],artist_prompt='Track how an image or relationship can shift meaning when its surroundings change. Use a personally generated motif to develop, clarify and extend your own metaphor.',
 phases=[('Establish a starting idea','Draw an object from observation and brainstorm possible associations. Select a direction grounded in your experience. Investigate artist practices that offer a way to develop the relationship between object and setting.'),('Generate alternatives','Make small painted drawings that change the relationship, such as scale, placement or surroundings. Keep the object and central question connected across the trials.'),('Reflect and clarify','Compare the drawings and identify which visual decisions make your meaning clearer. Develop a selected direction in further works that adjust the confusing or weak aspects.'),('Extend the idea','Find an implication not yet explored. Change the object’s role, the viewpoint or the setting to pursue that implication. Show how the new work emerges from critical evaluation of the earlier work.'),('Make the sequence legible','Select and order related drawings to show the path of the idea. Retain the alternatives and brief decision notes. Do not hide useful developments beneath decorative workbook presentation.')],
 evidence=['A related, ordered series of drawings, including painted drawings.','Visible changes that build on earlier ideas and respond to reflection.','Relevant artist connections and brief decision records.'],
 grades=[('Achievement','Build on a connected idea through related drawings.','Later works respond to the subject or concept established earlier.'),('Merit','Use analysis and reflection to make the idea clearer in subsequent work.','A deliberate change strengthens the meaning or resolves a pictorial problem.'),('Excellence','Critically evaluate and take the idea into further possibilities.','An established idea is developed into a new implication while remaining connected to the sequence.')],
 reflection='Where does the idea change rather than simply the appearance? Identify the earlier work that prompted that change.',teacher='Judge the development visible across the series. Keep the distinction from 2.2 clear: technical skill alone is not evidence of extending an idea. Use 91316 annotated exemplars to discuss the difference between a cosmetic variation and a conceptual or pictorial extension.',watch='Changing only the colours or enlarging the same composition may leave the idea undeveloped.'),
 dict(ref='2.4',as_id=91321,version=2,credits=12,assessment='External',title='A world worth returning to',short='Curate a systematic body of work',official='Produce a systematic body of work that shows understanding of art making conventions and ideas within painting',time='14–18 weeks',theme='What can I discover by returning to one personally meaningful world?',brief='Choose a personal subject-world: a familiar route, a domestic space, a collection of objects or another context you can investigate directly. Build a systematic painting inquiry in which related works generate and develop ideas. Curate the body so viewers can follow the decisions and discoveries.',materials='Your own source imagery and drawings, a visual diary, appropriate painting media and supports, and two portfolio panels for the physical painting route.',artists=['gossage', 'maughan', 'mehretu', 'hodgkins'],artist_prompt='Compare three ways of returning to a subject: memory and place, a repeated garden inquiry, and layered spatial investigation. Choose a sustained line of inquiry that can change through making.',
 phases=[('Open a focused inquiry','Identify a question worth returning to and gather your own visual sources. Investigate relevant established practices. Start with drawings and paint trials that open several plausible directions.'),('Generate related starting points','Explore different compositions, spatial relationships and methods. Identify the most useful possibilities for your question. Keep a record of why a particular direction deserves further work.'),('Develop and extend','Build related groups of paintings. Analyse what each group contributes, then use its findings in the next. Try a meaningful change that extends the idea rather than producing unrelated experiments.'),('Clarify and revisit','Review the developing body. Return to an earlier useful idea and reform it in response to what you now know. Where appropriate, use that return to generate a fresh line of work.'),('Select and sequence','Edit the works into an intelligible body. Test whether each work contributes to the progression. Complete and present the work in the current NZQA format, documenting the actual paint surfaces clearly.')],
 evidence=['A selected, ordered body of related painting work demonstrating generation and development.','Visible links between initial investigation, subsequent decisions and later outcomes.','A compliant portfolio and original process records supporting authenticity.'],
 grades=[('Achievement','Organise related works so generation and development are visible.','Editing and sequencing help the viewer follow the inquiry.'),('Merit','Build a purposeful body that also extends ideas.','Selected works take useful discoveries further for a clear artistic purpose.'),('Excellence','Create a fluent body through critical selection, clarification and regeneration.','Returning to earlier discoveries leads to convincing new work within a coherent inquiry.')],
 reflection='Which work makes the next step possible? Remove any work that adds volume without helping the inquiry progress.',teacher='This is an external standard with school grading and NZQA verification in 2026. Use the current specification and submission instructions, not an older physical-dispatch routine. The sequence is an optional teaching approach; students must make their own developmental decisions and portfolio selections within permitted assistance.',watch='Filling two panels is a presentation task; the assessment evidence is the progression of ideas and conventions.'),
 dict(ref='3.2',as_id=91446,version=2,credits=4,assessment='Internal',title='A language of paint',short='Demonstrate depth in conventions',official='Use drawing to demonstrate understanding of conventions appropriate to painting',time='4–5 weeks',theme='Which painting conventions best serve the idea I want to communicate?',brief='Investigate a self-selected subject through drawing and painting. Build an understanding of particular painting conventions, then critically choose and apply them toward an intended outcome. Aim for decisions that are visually convincing and appropriate to your own idea.',materials='Direct observations and your own imagery, drawing book, painting media and supports selected to suit your intention, plus materials for focused surface and colour tests.',artists=['rewiri', 'hindin', 'mehretu', 'cezanne'],artist_prompt='Investigate how composition, support and layering affect an intended outcome. Discuss the specific cultural contexts of the Māori practices; critically choose methods that are appropriate to your own inquiry.',
 phases=[('Name the pictorial problem','Define an intended outcome and a question about how the painting will work: for example, how compressed space might communicate unease. Gather your own subject material and identify relevant artist practices.'),('Investigate specific conventions','Select a small group of conventions such as figure-ground ambiguity, tonal intervals or the interaction of transparent and opaque layers. Test each with attention to the characteristics and constraints of the media.'),('Compare meaningful alternatives','Make related studies using different combinations. Ask what each combination does to the intended outcome. Identify what should be kept, changed or discarded.'),('Apply with intention','Develop more sustained drawings or paintings in which selected conventions operate together. Refine awkward or unresolved passages while preserving the intended pictorial effect.'),('Demonstrate your understanding','Present a focused set of work that makes your choices visible. Explain the relationship between intended outcome, chosen conventions and handling, using the actual work as evidence.')],
 evidence=['Practical drawings and painted studies showing understanding of relevant painting conventions.','Comparisons and sustained applications of selected conventions.','An intention, brief decision records and acknowledged sources.'],
 grades=[('Achievement','Select and use painting conventions with knowledge of their characteristics.','The practical work shows an understanding of the selected processes and their effects.'),('Merit','Purposefully apply particular conventions to achieve a chosen outcome.','The selected methods consistently serve the intended pictorial result.'),('Excellence','Critically select and fluently apply specific conventions with depth of understanding.','The combination of methods and their skilful application resolves the intended visual problem convincingly.')],
 reflection='What does your chosen convention allow that an alternative would not? Point to a comparison in your studies.',teacher='Look for depth of understanding demonstrated through practical selection and use. A long survey of many artists is not a substitute. Moderate against 91446 exemplars; distinguish the informed application here from the systematic idea clarification required in 3.3.',watch='Polish alone does not demonstrate critical selection of specific conventions.'),
 dict(ref='3.3',as_id=91451,version=2,credits=4,assessment='Internal',title='Return with a difference',short='Clarify, extend and regenerate',official='Systematically clarify ideas using drawing informed by established painting practice',time='5–6 weeks',theme='What happens when I return to an earlier idea with a new question?',brief='Use a related sequence of drawing and painting to clarify a personal idea, extend it and explore regeneration. Start with your own previous artwork or a new initial investigation. Treat the sequence as a thinking process, in which evaluation leads to changes in subsequent work.',materials='Your own earlier studies, fresh observed sources where needed, drawing and painting materials selected for the inquiry, and a way to record the sequence and decisions.',artists=['cotton', 'pick', 'bradford', 'hodgkins'],artist_prompt='Use the models to investigate revisiting, re-forming and revealing earlier decisions. Make a new direction grow from your own previous work and evaluate what changed.',
 phases=[('Locate a live problem','Review your own work and identify an unresolved pictorial or conceptual issue. Choose established painting practices that can help you investigate it. Frame a question that can be answered through further drawing.'),('Clarify in sequence','Make related drawings that analyse and adjust the issue. Use each result to decide the next step. Keep the relationship between the works legible.'),('Critically extend','Evaluate which decisions are productive and pursue an implication of them. Change the relationship between form and idea, rather than adding a new effect without a reason.'),('Revisit and regenerate','Return to an earlier drawing or idea. Re-form it using discoveries from later work to create a new direction. Maintain the conceptual connection while testing a different visual possibility.'),('Trace the thinking','Order the drawings to show progression. Identify where clarification, extension or regeneration actually happens. Retain brief evaluations, but allow the visual sequence to carry the main evidence.')],
 evidence=['A systematic sequence of related drawings or paintings informed by established practice.','Visible analysis and development, with further possibilities pursued where appropriate.','Earlier work needed to understand any regenerated idea, plus source acknowledgements.'],
 grades=[('Achievement','Clarify an idea systematically through analysis, reflection and further drawing.','Each connected work helps resolve or sharpen the initial issue.'),('Merit','Extend the idea through critical evaluation and further development.','The sequence pursues a new implication of an earlier discovery.'),('Excellence','Regenerate through critically revisiting and reforming ideas from your own earlier work.','A return produces a new direction that extends the inquiry rather than restyling an image.')],
 reflection='Identify the return point. What did you know at that moment that you did not know when you made the original work?',teacher='Regeneration is required for Excellence here, while in 3.4 regeneration is present at every grade. Make that difference explicit. Students may use existing personal work as a starting point, but assess the new evidence against this standard. Agree and record how any evidence used across standards is judged independently.',watch='A sudden unrelated new subject is not necessarily regeneration; make the relationship to the previous idea visible.'),
 dict(ref='3.4',as_id=91456,version=2,credits=14,assessment='External',title='Build your own visual world',short='Integrate, regenerate and synthesise',official='Produce a systematic body of work that integrates conventions and regenerates ideas within painting practice',time='18–22 weeks',theme='How can my painting inquiry become a coherent, personal visual world?',brief='Develop an independent painting inquiry grounded in a personally meaningful proposition. Bring conventions together, return to your own ideas and reform them through new work. Curate a systematic body in which the progression, integration and regeneration are visible across the whole inquiry.',materials='Your own research and visual sources, selected painting media and supports, a working diary, and three hinged portfolio panels for the physical painting route.',artists=['karaka', 'cotton', 'mehretu', 'bradford', 'hodgkins'],artist_prompt='Compare how a painting language brings material decisions together with a sustained position or question. Integrate selected conventions and regenerate ideas within your own culturally situated inquiry.',
 phases=[('Frame an independent inquiry','Develop a proposition with enough scope for sustained investigation. Gather and generate original imagery, examine relevant artist practices and identify pictorial relationships you want to investigate.'),('Bring conventions together','Make initial works that combine selected methods toward your intention. Test how the conventions interact; avoid simply placing one artist’s manner beside another’s. Select a promising relationship for further work.'),('Develop and regenerate','Evaluate the work, return to an earlier productive idea and re-form it in new paintings. Repeat the cycle as the inquiry develops. Regeneration must be evident in the body, not reserved for an optional final experiment.'),('Deepen the relationships','Critically compare the conceptual and technical decisions. Refine the relationship between sources, methods and intentions, and explore further options. Seek an integrated personal language rather than a sequence of borrowed appearances.'),('Curate the whole body','Select and order the work so the inquiry can be followed across the portfolio. Look for gaps, redundant repetition and unsupported changes. Resolve the presentation, complete authenticity documentation and follow the current external specifications.')],
 evidence=['A systematic, edited and ordered painting body that integrates conventions and regenerates ideas.','Clear links between previous work, revisited ideas and new possibilities.','A compliant portfolio with source and authenticity documentation.'],
 grades=[('Achievement','Combine conventions and regenerate ideas within an ordered, related body.','The body visibly brings methods together and reforms earlier ideas in new work.'),('Merit','Integrate particular conventions purposefully and regenerate selected ideas toward an intention.','Considered combinations and returns contribute clearly to the intended outcomes.'),('Excellence','Synthesise critically selected ideas and methods, regenerating a depth of ideas.','Sources, conventions and personal intentions work as an integrated language that opens further possibilities.')],
 reflection='Where do conventions become your own language? Identify a passage in the body where several sources or methods have become inseparable from your intention.',teacher='Check regeneration at Achievement as well as at higher grades. Assess the body holistically using the current schedule and exemplars; separate strong technique from the depth and integration of ideas. The 2026 physical painting route is a three-panel portfolio. Keep work student-led and assistance within the annual conditions.',watch='Three panels of technically accomplished paintings can still lack integrated conventions or regenerated ideas.')
]
